                    <button id="next-page" class="nav-button">下一页</button>
                </div>
            </div>
        </div>
    </div>

    <script>
    // 这是被 findRegex 捕获并注入的日记内容
    const matchedDiaryContent = `$1`;

    const defaultDiaryData = `[2023年10月15日 星期日｜好奇｜晴]
    当你看到这个页面的时候可能格式错了！<gl>点击编辑检查一下</gl>，<wu>非常感谢</wu>。<sh>这是一个加粗示例</sh>，<cr>这是一个删除线示例</cr>。`;

        const tagMappings = { gl: (c) => `<span class="glow-text">${c}</span>`, sk: (c) => `<span class="sticker-text">${c}</span>`, wu: (c) => `<span class="wavy-underline">${c}</span>`, sh: (c) => `<span class="bold-text">${c}</span>`, cr: (c) => `<span class="strikethrough-text">${c}</span>` };
        let allDiaryEntries = [], currentPageIndex = 0;

        function convertTags(text) {
            Object.keys(tagMappings).forEach(tag => {
                text = text.replace(new RegExp(`<${tag}>(.*?)<\/${tag}>`, 'g'), (_, c) => tagMappings[tag](c));
            });
            return text;
        }

        function parseMultipleDiaryEntries(diaryText) {
            const dateMarkers = diaryText.match(/\[\d{4}年\d{1,2}月\d{1,2}日\s星期[一二三四五六日]?｜.*?｜.*?\]/g);
            if (!dateMarkers) return [];
            const entries = [];
            for (let i = 0; i < dateMarkers.length; i++) {
                const metaMatch = dateMarkers[i].match(/\[(.*?)｜(.*?)｜(.*?)\]/);
                if (!metaMatch) continue;
                const [_, date, mood, weather] = metaMatch;
                const endIdx = (i < dateMarkers.length - 1) ? diaryText.indexOf(dateMarkers[i+1]) : diaryText.length;
                let content = diaryText.substring(diaryText.indexOf(dateMarkers[i]) + dateMarkers[i].length, endIdx).trim();
                entries.push({ date, mood, weather, content: convertTags(content) });
            }
            return entries;
        }

        function createDiaryEntryHTML(data) {
            return `<div class="diary-entry"><div class="diary-date">${data.date}</div><div class="diary-info"><span>心情: ${data.mood}</span><span>天气: ${data.weather}</span></div><div class="diary-text">${data.content}</div></div>`;
        }

        function displayCurrentDiaryPage() {
            const contentEl = document.getElementById('diary-content');
            if (allDiaryEntries.length === 0) {
                contentEl.innerHTML = '<div class="diary-entry">未找到日记数据</div>';
                document.getElementById('diary-nav').style.display = 'none';
                return;
            }
            contentEl.innerHTML = createDiaryEntryHTML(allDiaryEntries[currentPageIndex]);
            document.getElementById('current-page-num').textContent = currentPageIndex + 1;
            document.getElementById('total-pages').textContent = allDiaryEntries.length;
            document.getElementById('prev-page').disabled = currentPageIndex === 0;
            document.getElementById('next-page').disabled = currentPageIndex === allDiaryEntries.length - 1;
            document.getElementById('diary-nav').style.display = allDiaryEntries.length > 1 ? 'flex' : 'none';
            contentEl.scrollTop = 0;
        }

        function navigateTo(direction) {
            const newIndex = currentPageIndex + direction;
            if (newIndex >= 0 && newIndex < allDiaryEntries.length) {
                currentPageIndex = newIndex;
                displayCurrentDiaryPage();
            }
        }

        function init() {
            // 优先使用由 findRegex 注入的内容
            let diaryText = matchedDiaryContent;

            // 如果注入的内容为空，则解析默认内容
            if (!diaryText || diaryText.trim() === '') {
                diaryText = defaultDiaryData;
            }

            allDiaryEntries = parseMultipleDiaryEntries(diaryText);

            // 如果解析后仍然没有内容（例如，格式完全错误），则再次使用默认内容作为最终保障
            if (allDiaryEntries.length === 0) {
                 allDiaryEntries = parseMultipleDiaryEntries(defaultDiaryData);
            }

            displayCurrentDiaryPage();
            document.getElementById('prev-page').addEventListener('click', () => navigateTo(-1));
            document.getElementById('next-page').addEventListener('click', () => navigateTo(1));
        }

        init();
    </script>
